`,"../../../packages/print-studio/dist/locales/types.d.ts":`/** 译文结构：嵌套的键值树，叶子节点为文案字符串。 */
export interface Translations {
    [key: string]: string | Translations;
}
/** 语言包加载器：按语言代码异步返回译文。 */
export type LocaleLoader = (locale: string) => Promise<Translations>;
/** 语言持久化存储契约。 */
export interface LocaleStorage {
    /** 读取持久化的语言代码；无记录时返回 \`null\`。 */
    get(): null | string;
    /** 持久化语言代码。 */
    set(locale: string): void;
}
