/** 判断值是否为格式合法的语言代码。 */
export declare function isValidLocale(locale: unknown): locale is string;
/** 判断值是否为结构合法的译文树。 */
export declare function isTranslations(value: unknown): value is Translations;
/** 深度合并多个译文树，靠后的源覆盖靠前的同名 key。 */
export declare function mergeTranslations(sources: Translations[]): Translations;
/** 判断译文树中是否存在至少一条文案字符串。 */
